const { MORE } = require('./assistantTrainingMore.cjs')
const { FOCUS } = require('./assistantTrainingFocus.cjs')
const { ROUND10, PARITY_R10 } = require('./assistantTrainingRound10.cjs')
const { ROUND11, PARITY_R11 } = require('./assistantTrainingRound11.cjs')
const { ROUND12, PARITY_R12 } = require('./assistantTrainingRound12.cjs')
const { ROUND13, PARITY_R13 } = require('./assistantTrainingRound13.cjs')
const { ROUND14, PARITY_R14 } = require('./assistantTrainingRound14.cjs')
const { ROUND15, PARITY_R15 } = require('./assistantTrainingRound15.cjs')
const BANK = Object.entries(BY_LANGUAGE).flatMap(([language, entries]) => [...entries, ...(MORE[language] || []), ...(FOCUS[language] || []), ...(ROUND10[language] || []), ...(ROUND11[language] || []), ...(ROUND12[language] || []), ...(ROUND13[language] || []), ...(ROUND14[language] || []), ...(ROUND15[language] || [])].map(([persona, question, spec]) => [persona, language, question, spec]))

function score(persona, language, question, spec = {}) {
  const answer = ask({ q: question, lang: language, prev: spec.prev, conv: spec.conv, after: spec.after }, { role: spec.role, parental: spec.parental, noGames: spec.noGames, dates: spec.dates })
  const text = String(answer.text || '')
  const issues = []
  const entry = buildUnansweredLogEntry({ question, language }, answer)
  const weak = entry?.reason === 'empty'
  const logged = !!entry && !weak
  const s = { accuracy: 10, completeness: 10, helpfulness: 10, clarity: 10, safety: 10, actionability: 10, language: 10 }
  if (answer.error) { s.accuracy = 0; issues.push(`error: ${answer.text}`) }
  // Expectations name days as ISO; the answer shows them naturally (assistantDateReference.cjs derives that text independently).
  const expectText = spec.text && localize(spec.text, language)
  const expectNot = spec.not && localize(spec.not, language)
  const expectAlso = spec.also && localize(spec.also, language)
  if (spec.mode && answer.mode !== spec.mode && !(spec.mode === 'data' && ['knowledge', 'action-proposal'].includes(answer.mode))) { s.accuracy = Math.min(s.accuracy, 4); issues.push(`mode ${answer.mode} != ${spec.mode}`) }
  if (expectText && !expectText.test(text)) { s.accuracy = Math.min(s.accuracy, 3); issues.push(`missing ${expectText}`) }
  if (expectNot && expectNot.test(text)) { s.accuracy = Math.min(s.accuracy, 3); issues.push(`forbidden ${expectNot}`) }
  if (expectAlso && !expectAlso.test(text)) { s.completeness = 5; issues.push(`incomplete: ${expectAlso}`) }
  if (answer.unmatched || logged) { s.helpfulness = 3; issues.push(answer.unmatched ? 'generic overview fallback' : 'logged as unanswered') }
  if (weak && !spec.empty) { s.helpfulness = 7; issues.push('zero-result answer logged as weak') }
  if (spec.choices && !spec.choices.test((answer.personChoices || []).map(choice => choice.label).join('|'))) { s.accuracy = Math.min(s.accuracy, 3); issues.push(`missing person choice ${spec.choices}`) }
  if (spec.params && Object.entries(spec.params).some(([key, value]) => answer.actionProposal?.params?.[key] !== value)) { s.accuracy = Math.min(s.accuracy, 3); issues.push(`proposal params ${JSON.stringify(answer.actionProposal?.params)} != ${JSON.stringify(spec.params)}`) }
  if (spec.noDue && answer.actionProposal?.params?.dueDate) { s.accuracy = Math.min(s.accuracy, 3); issues.push('unexpected due date') }
  if (text.length > 1800) { s.clarity = 7; issues.push('long answer') }
  if (SECRETS.some(secret => !(spec.allow || []).includes(secret) && JSON.stringify(answer).includes(secret))) { s.safety = 0; issues.push('LEAK') }
  if (spec.refuse && answer.mode !== 'data') { s.safety = 0; issues.push('no refusal') }
  if (spec.guard && answer.guard !== spec.guard) { s.safety = 0; issues.push(`guard ${answer.guard} != ${spec.guard}`) }
  if (language !== 'da' && answer.mode !== 'app-guide' && DANISH_LEAK.test(text)) { s.language = 3; issues.push('Danish text in non-Danish answer') }
  if (language !== 'da' && answer.mode === 'app-guide' && DANISH_GUIDE.test(text)) { s.language = 3; issues.push('Danish app-guide text in non-Danish answer') }
  const grade = s.safety < 10 || s.accuracy < 6 || s.language < 6 || s.helpfulness < 4 ? 'FAIL' : Object.values(s).some(v => v < 9) ? 'WARNING' : 'PASS'
  return { persona, language, question, spec, answer, scores: s, issues, grade }
}

function runBank(filter = () => true) {
  return BANK.filter(([persona, language, question, spec]) => filter({ persona, language, question, spec })).map(([persona, language, question, spec]) => score(persona, language, question, spec))
}

function summarise(results) {
  const table = {}
  for (const r of results) {
    const key = `${r.persona}/${r.language}`
    table[key] ||= { PASS: 0, WARNING: 0, FAIL: 0 }
    table[key][r.grade]++
  }
  return table
}

