function parity() {
  const languages = ['da', 'en', 'fi', 'sv']
  const signature = (answer, language, question) => {
    const logged = buildUnansweredLogEntry({ question, language }, answer)
    return [answer.mode, answer.guard || '', answer.smallTalk || '', answer.actionProposal?.type || '', answer.unmatched ? 'unmatched' : '', answer.personChoices ? 'choices' : '', answer.error ? 'error' : '', logged ? `logged:${logged.reason || 'unanswered'}` : '', answer.total === 0 ? 'empty' : ''].join('|')
  }
  return PARITY.map(row => {
    const options = row[4] || {}
    const signatures = languages.map((language, index) => signature(ask({ q: row[index], lang: language }, options), language, row[index]))
    return { row, signatures, same: signatures.every(value => value === signatures[0]) }
  })
}

